  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 9, $j$3.1 Energy, ATP and Metabolism$j$, $j${"readings": [{"title": "Isaiah 40 (King James Version)", "url": "/portal/bible/Isaiah/40"}], "body": "All living things need energy. Energy cannot be created or destroyed, but it can change form. The sun is the source of energy for nearly all life on earth. Isaiah 40:31 says, But they that wait upon the LORD shall renew their strength; they shall mount up with wings as eagles; they shall run, and not be weary; and they shall walk, and not faint.\n\nAutotrophs (producers) make their own food. Plants, algae and some bacteria use light energy in photosynthesis.\nHeterotrophs (consumers) get energy by eating other organisms. Animals, fungi and many bacteria are heterotrophs.\n\nCells use a small molecule called ATP (adenosine triphosphate) as an energy currency. When the cell breaks the bond of the third phosphate, ATP becomes ADP (adenosine diphosphate) and releases energy for work such as muscle contraction, active transport and building molecules. Cells then recharge ADP back into ATP using energy from food or light. A working muscle cell can recycle its ATP many times a minute.\n\nMetabolism is the sum of all chemical reactions in a cell. Anabolic reactions build larger molecules and need energy (for example, making proteins). Catabolic reactions break down molecules and release energy (for example, digesting food).\n\nThe big picture: Photosynthesis stores the energy of sunlight in sugar. Cellular respiration releases the energy of sugar into ATP. The two processes use each other's products, so they form a cycle of matter, with a one way flow of energy through the ecosystem.\n\nYour task: (1) Compare an autotroph and a heterotroph and give an example of each. (2) Explain how ATP works like a rechargeable battery. (3) Tell the difference between anabolic and catabolic reactions.\n\nFlorida standards: SC.912.L.18.9.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.L.18.9", "script": "Welcome to Unit 3. This is Dr. Jenkins. Listen, everything alive needs energy, and Isaiah forty and thirty one says, But they that wait upon the LORD shall renew their strength; they shall mount up with wings as eagles; they shall run, and not be weary; and they shall walk, and not faint. Today we learn how cells renew their strength.\n\nNow watch this. Energy cannot be created or destroyed. It changes form. The sun is the source of energy for nearly all life. Autotrophs, also called producers, make their own food. Plants, algae and some bacteria use light energy in photosynthesis. Heterotrophs, or consumers, get energy by eating other organisms. Animals, fungi and many bacteria are heterotrophs.\n\nLook at this. Cells use a small molecule called ATP, adenosine triphosphate, as an energy currency. When the cell breaks the bond of the third phosphate, ATP becomes ADP, adenosine diphosphate, and energy is released for work, like muscle contraction, active transport and building molecules. Then the cell recharges ADP back into ATP using energy from food or light. It works like a rechargeable battery.\n\nMetabolism is the sum of all the chemical reactions in a cell. Anabolic reactions build larger molecules and need energy, like making proteins. Catabolic reactions break molecules down and release energy, like digesting food.\n\nHere is the big picture. Photosynthesis stores the energy of sunlight in sugar. Cellular respiration releases the energy of sugar as ATP. The products of one are the ingredients of the other, so matter cycles, but energy flows one way through an ecosystem.\n\nYour task today. Compare an autotroph and a heterotroph. Explain how ATP works like a battery. And tell the difference between anabolic and catabolic reactions. Take the four question check when you finish.\n\nStrength is renewed from a source outside ourselves. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.1 Energy, ATP and Metabolism$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 10, $j$3.2 Photosynthesis$j$, $j${"readings": [{"title": "Psalm 104 (King James Version)", "url": "/portal/bible/Psalms/104"}], "body": "Photosynthesis is the process by which producers use light energy to make sugar from carbon dioxide and water, and release oxygen. Psalm 104:14 says, He causeth the grass to grow for the cattle, and herb for the service of man: that he may bring forth food out of the earth.\n\nEquation: 6 CO2 (carbon dioxide) + 6 H2O (water) + light energy produce C6H12O6 (glucose) + 6 O2 (oxygen).\n\nWhere it happens: in the chloroplast of plant cells. Chlorophyll, the green pigment, absorbs mostly red and blue light and reflects green light, which is why leaves look green.\n\nTwo stages:\nLight dependent reactions (in the thylakoid membranes): Light is absorbed, water is split, oxygen is released, and ATP and NADPH are made.\nCalvin cycle (in the stroma): Uses ATP and NADPH to build glucose from carbon dioxide. It does not need light directly.\n\nHow plants get what they need: Carbon dioxide enters through tiny openings in leaves called stomata, which are opened and closed by guard cells. Water travels up from the roots. Sugars made in leaves travel through the phloem to other parts.\n\nFactors that affect the rate: light intensity, carbon dioxide level, temperature and water. The rate rises with more light, then levels off when another factor becomes limiting.\n\nImportance: Photosynthesis produces the oxygen we breathe and the food at the base of nearly every food chain. It also removes carbon dioxide from the air.\n\nYour task: (1) Write the photosynthesis equation in words. (2) Tell where the oxygen released comes from. (3) Explain why a plant leaf looks green.\n\nFlorida standards: SC.912.L.18.9.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.L.18.9", "script": "Welcome back. Dr. Jenkins here. Listen, Psalm one hundred four and fourteen says, He causeth the grass to grow for the cattle, and herb for the service of man: that he may bring forth food out of the earth. Today we see how He does it, through photosynthesis.\n\nPhotosynthesis is the process by which producers use light energy to make sugar from carbon dioxide and water, and release oxygen. In words, six carbon dioxide plus six water plus light energy produce one glucose plus six oxygen. It happens in the chloroplast. Chlorophyll, the green pigment, absorbs mostly red and blue light and reflects green light, which is why leaves look green.\n\nNow watch this. There are two stages. In the light dependent reactions, which happen in the thylakoid membranes, light is absorbed, water is split, oxygen is released, and ATP and NADPH are made. Then in the Calvin cycle, which happens in the stroma, the ATP and NADPH are used to build glucose from carbon dioxide. The Calvin cycle does not need light directly, but it depends on what the light reactions made.\n\nLook at how plants get what they need. Carbon dioxide enters through tiny openings called stomata, opened and closed by guard cells. Water comes up from the roots. Sugars travel through the phloem to the rest of the plant.\n\nWhat speeds it up? Light intensity, carbon dioxide level, temperature and water. The rate rises with more light, then levels off when another factor becomes limiting.\n\nAnd why does it matter? Photosynthesis gives us the oxygen we breathe and the food at the bottom of nearly every food chain, and it removes carbon dioxide from the air.\n\nYour task today. Write the equation in words. Tell where the released oxygen comes from. And explain why a leaf looks green. Take the four question check when you finish.\n\nHe supplies our needs from the earth. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.2 Photosynthesis$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 11, $j$3.3 Cellular Respiration and Fermentation$j$, $j${"readings": [{"title": "Genesis 2 (King James Version)", "url": "/portal/bible/Genesis/2"}], "body": "Cellular respiration releases the energy stored in food and stores it in ATP. Genesis 2:7 says, And the LORD God formed man of the dust of the ground, and breathed into his nostrils the breath of life; and man became a living soul.\n\nEquation: C6H12O6 (glucose) + 6 O2 (oxygen) produce 6 CO2 (carbon dioxide) + 6 H2O (water) + ATP (about 36 to 38 per glucose).\n\nThis is nearly the reverse of photosynthesis. It happens in all living cells, plants and animals alike, and the later stages occur in the mitochondrion.\n\nStages:\nGlycolysis (cytoplasm): One glucose is split into two pyruvate. It makes a small amount of ATP (net 2) and does not need oxygen.\nKrebs cycle (mitochondrial matrix): Pyruvate is broken down and carbon dioxide is released.\nElectron transport chain (inner mitochondrial membrane): Uses oxygen as the final electron acceptor and makes most of the ATP (about 32 to 34). Oxygen combines with hydrogen to make water.\n\nAerobic respiration needs oxygen. Anaerobic processes do not.\nFermentation follows glycolysis when oxygen is absent. Lactic acid fermentation happens in muscle cells during hard exercise, making lactic acid, and in some bacteria used to make yogurt. Alcoholic fermentation happens in yeast, making ethanol and carbon dioxide, which makes bread rise. Fermentation makes only 2 ATP per glucose.\n\nComparison: Photosynthesis uses carbon dioxide and water and stores energy; respiration uses glucose and oxygen and releases energy. Together they cycle carbon and oxygen through living things.\n\nYour task: (1) Write the respiration equation in words. (2) Tell why your breathing and heart rate rise during exercise. (3) Explain why bread dough rises.\n\nFlorida standards: SC.912.L.18.9.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.L.18.9", "script": "Welcome back. Dr. Jenkins here. Listen, Genesis two and seven says, And the LORD God formed man of the dust of the ground, and breathed into his nostrils the breath of life; and man became a living soul. Every breath you take supports a process happening in your cells right now, cellular respiration.\n\nNow watch this. Cellular respiration releases the energy stored in food and puts it into ATP. In words, one glucose plus six oxygen produce six carbon dioxide plus six water plus ATP, about thirty six to thirty eight per glucose. It is nearly the reverse of photosynthesis, and it happens in all living cells, plants and animals alike.\n\nLook at the stages. Glycolysis happens in the cytoplasm. One glucose is split into two pyruvate, with a net gain of two ATP, and it needs no oxygen. The Krebs cycle takes place in the mitochondrial matrix, where pyruvate is broken down and carbon dioxide is released. The electron transport chain is on the inner mitochondrial membrane. It uses oxygen as the final electron acceptor, makes most of the ATP, and oxygen combines with hydrogen to make water.\n\nWhat if there is no oxygen? Fermentation follows glycolysis. Lactic acid fermentation happens in your muscles during hard exercise, and in bacteria used to make yogurt. Alcoholic fermentation happens in yeast, making ethanol and carbon dioxide, and that carbon dioxide makes bread rise. Fermentation makes only two ATP per glucose, so it is a short term rescue, not a long term plan.\n\nCompare the two. Photosynthesis uses carbon dioxide and water and stores energy. Respiration uses glucose and oxygen and releases energy. Together they cycle carbon and oxygen through living things.\n\nYour task today. Write the respiration equation in words. Tell why breathing and heart rate rise during exercise. And explain why bread dough rises. Take the four question check when you finish.\n\nHe gave breath and He gives purpose. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.3 Cellular Respiration and Fermentation$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 12, $j$3.4 Enzymes and Reaction Rates$j$, $j${"readings": [{"title": "Psalm 1 (King James Version)", "url": "/portal/bible/Psalms/1"}], "body": "Enzymes make life possible. Without them, reactions in the body would be too slow. Psalm 1:3 says, And he shall be like a tree planted by the rivers of water, that bringeth forth his fruit in his season; his leaf also shall not wither; and whatsoever he doeth shall prosper.\n\nReview: An enzyme is a protein catalyst. It lowers the activation energy, the energy needed to start a reaction, so the reaction goes faster. The substrate fits into the active site, forming an enzyme substrate complex. The enzyme releases the products and can be used again. Names often end in ase, such as amylase, which digests starch, and lipase, which digests fats.\n\nFactors that affect enzyme activity:\nTemperature: The rate rises with warmth up to an optimum, then falls sharply when the enzyme denatures. Human enzymes work best near 37 degrees Celsius.\npH: Each enzyme has an optimum pH. Pepsin in the stomach works best near pH 2. Amylase in the mouth works near pH 7.\nSubstrate concentration: More substrate raises the rate until all active sites are busy (saturation).\nEnzyme concentration: More enzyme gives a faster rate if substrate is available.\nInhibitors can block the active site and slow the reaction. This is one way cells control reactions.\n\nExample: Catalase in cells breaks down hydrogen peroxide, a harmful waste, into water and oxygen. Bubbles of oxygen show the reaction rate in liver or potato.\n\nReading a graph: A bell shaped curve of rate versus temperature peaks at the optimum, then drops as the enzyme denatures.\n\nYour task: (1) Explain how an enzyme lowers activation energy. (2) Sketch or describe a graph of rate versus temperature for a human enzyme. (3) Predict what happens to pepsin in a pH 8 solution.\n\nFlorida standards: SC.912.L.18.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.L.18.1", "script": "Welcome back. Dr. Jenkins here. Listen, Psalm one and three says, And he shall be like a tree planted by the rivers of water, that bringeth forth his fruit in his season; his leaf also shall not wither; and whatsoever he doeth shall prosper. In your cells, enzymes help every reaction happen in its season.\n\nLet us review. An enzyme is a protein catalyst. It lowers the activation energy, the energy needed to start a reaction, so the reaction goes faster. The substrate fits into the active site, forming the enzyme substrate complex. Then the products are released and the enzyme can be used again. Names often end in a s e, like amylase, which digests starch, and lipase, which digests fats.\n\nNow watch this. What changes how fast an enzyme works? Temperature. The rate rises with warmth up to an optimum, then falls sharply as the enzyme denatures. Human enzymes work best near thirty seven degrees Celsius. Next, pH. Each enzyme has an optimum. Pepsin in the stomach works best near pH two. Amylase in the mouth works near pH seven. Then substrate concentration. More substrate raises the rate until all the active sites are busy, which is called saturation. More enzyme gives a faster rate if there is substrate to work on. And inhibitors can block the active site and slow the reaction, which is one way cells control reactions.\n\nLook at this example. Catalase breaks down hydrogen peroxide, a harmful waste, into water and oxygen. When you drop a piece of liver or potato into peroxide, the bubbles of oxygen show you the rate.\n\nOn a graph, rate versus temperature makes a bell shaped curve. It climbs to the optimum and then drops as the enzyme denatures.\n\nYour task today. Explain how an enzyme lowers activation energy. Describe a graph of rate versus temperature. And predict what happens to pepsin in a pH eight solution. Take the four question check when you finish.\n\nFruit comes in its season when the conditions are right. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.4 Enzymes and Reaction Rates$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 3, $j$Assessment 3: Energy Flow and Enzyme Investigation$j$, $j${"prompt": "Part 1: Energy Cycle Diagram. Draw or describe a labeled diagram that shows how photosynthesis and cellular respiration are connected. Include the reactants and products of each process, where each occurs in the cell, and the role of ATP. Psalm 104:14 says, He causeth the grass to grow for the cattle, and herb for the service of man: that he may bring forth food out of the earth.\n\nPart 2: Comparison Chart. Make a table that compares photosynthesis and cellular respiration in at least five ways (for example, reactants, products, organelle, energy change, who does it).\n\nPart 3: Enzyme Investigation. Design an investigation to test how temperature or pH affects an enzyme such as catalase in potato or liver. Identify the independent variable, dependent variable, at least three controlled variables and your hypothesis. Describe the graph you expect.\n\nPart 4: Application. Explain in a paragraph why athletes feel a burning in their muscles during a sprint and how the body recovers.\n\nPart 5: Reflection. In at least 60 words, explain how the flow of energy from the sun through plants to us points to the care of the Creator.", "rubric": "70 points. Energy cycle diagram: 16 points. Comparison chart: 12 points. Enzyme investigation: 20 points. Application paragraph: 10 points. Reflection: 8 points. Clear work and complete sentences: 4 points. A score of 49 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 3: Energy Flow and Enzyme Investigation$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 3, $j$Discussion 3: Strength Renewed$j$, $j${"prompt": "Write a post of at least 120 words that (1) explains in your own words how photosynthesis and cellular respiration depend on each other, (2) describes why ATP is called the energy currency of the cell, (3) tells how the idea that all our food energy began as sunlight can shape how we give thanks and avoid waste, and (4) connects your answer to Isaiah 40:31, which says, But they that wait upon the LORD shall renew their strength; they shall mount up with wings as eagles; they shall run, and not be weary; and they shall walk, and not faint. Then write a respectful reply of at least 40 words to another student, or answer this question: Why does the rate of photosynthesis level off even when light keeps increasing? Keep your language clean and your tone kind."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 3: Strength Renewed$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 11, $j$Check 3.1: Energy, ATP and Metabolism$j$, $j${"questions": [{"q": "An organism that makes its own food from light energy is a(n):", "options": ["Predator", "Heterotroph", "Autotroph", "Decomposer only"]}, {"q": "When ATP loses its third phosphate it becomes:", "options": ["ADP", "Glucose", "DNA", "Water"]}, {"q": "Reactions that break down molecules and release energy are:", "options": ["Catabolic", "Anabolic", "Photosynthetic only", "Not chemical"]}, {"q": "The ultimate source of energy for most ecosystems is the:", "options": ["Soil", "Sun", "Moon", "Wind"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.1: Energy, ATP and Metabolism$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,0,1}'::int[], array[$j$Autotrophs such as plants make food through photosynthesis.$j$,$j$ATP becomes ADP and releases energy.$j$,$j$Catabolic reactions break molecules apart.$j$,$j$Sunlight is captured by producers and drives food webs.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.1: Energy, ATP and Metabolism$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 12, $j$Check 3.2: Photosynthesis$j$, $j${"questions": [{"q": "The reactants of photosynthesis are:", "options": ["Glucose and oxygen", "Carbon dioxide and water", "Oxygen and water", "ATP and DNA"]}, {"q": "Oxygen released in photosynthesis comes from the splitting of:", "options": ["Chlorophyll", "Water", "Glucose", "Carbon dioxide"]}, {"q": "The Calvin cycle occurs in the:", "options": ["Mitochondrion", "Stroma of the chloroplast", "Cell membrane", "Nucleus"]}, {"q": "Leaves look green because chlorophyll:", "options": ["Absorbs green light", "Has no color", "Reflects green light", "Makes oxygen"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.2: Photosynthesis$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,1,1,2}'::int[], array[$j$Plants use carbon dioxide and water plus light energy.$j$,$j$Water is split in the light dependent reactions.$j$,$j$The stroma is the fluid around the thylakoids.$j$,$j$Green light is mostly reflected back to our eyes.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.2: Photosynthesis$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 13, $j$Check 3.3: Cellular Respiration and Fermentation$j$, $j${"questions": [{"q": "Most of the ATP in aerobic respiration is made in the:", "options": ["Electron transport chain", "Calvin cycle", "Cytokinesis", "Glycolysis"]}, {"q": "Glycolysis takes place in the:", "options": ["Chloroplast", "Cell wall", "Cytoplasm", "Nucleus"]}, {"q": "Yeast fermentation produces:", "options": ["Ethanol and carbon dioxide", "Glucose and oxygen", "Water only", "Lactic acid and oxygen"]}, {"q": "Compared with aerobic respiration, fermentation makes:", "options": ["No energy and no products", "The same amount of ATP", "Much less ATP", "Much more ATP"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.3: Cellular Respiration and Fermentation$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,2,0,2}'::int[], array[$j$The electron transport chain makes about 32 to 34 ATP.$j$,$j$Glycolysis occurs in the cytoplasm and needs no oxygen.$j$,$j$Alcoholic fermentation makes ethanol and carbon dioxide.$j$,$j$Fermentation yields only about 2 ATP per glucose.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.3: Cellular Respiration and Fermentation$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 14, $j$Check 3.4: Enzymes and Reaction Rates$j$, $j${"questions": [{"q": "An enzyme speeds up a reaction by:", "options": ["Lowering the activation energy", "Raising the pH only", "Becoming part of the product", "Adding more substrate"]}, {"q": "Extreme heat usually stops an enzyme because it:", "options": ["Makes the substrate larger", "Denatures the enzyme and changes its shape", "Turns it into a lipid", "Adds more phosphate"]}, {"q": "Catalase breaks down hydrogen peroxide into:", "options": ["Water and oxygen", "Carbon dioxide and starch", "Glucose and oxygen", "Protein and water"]}, {"q": "When every active site is busy, adding more substrate will:", "options": ["Double the rate", "Destroy the enzyme", "Not increase the rate further", "Stop the reaction at once"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.4: Enzymes and Reaction Rates$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,0,2}'::int[], array[$j$Catalysts lower the energy needed to start a reaction.$j$,$j$A changed shape means the active site no longer fits the substrate.$j$,$j$Bubbles of oxygen show catalase working.$j$,$j$The enzyme is saturated, so the rate levels off.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.4: Enzymes and Reaction Rates$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 15, $j$Unit Quiz 3: Energy for Life, Photosynthesis and Respiration$j$, $j${"questions": [{"q": "Which organelle is the site of photosynthesis?", "options": ["Ribosome", "Vacuole", "Chloroplast", "Mitochondrion"]}, {"q": "Which pair shows the products of photosynthesis?", "options": ["ATP and ADP", "Carbon dioxide and water", "Lactic acid and ethanol", "Glucose and oxygen"]}, {"q": "Cellular respiration in aerobic cells requires:", "options": ["Only carbon dioxide", "Oxygen and glucose", "Light and chlorophyll", "Only water"]}, {"q": "The first stage of respiration, glycolysis, occurs:", "options": ["In the nucleus with oxygen", "In the cytoplasm without oxygen", "In the chloroplast", "Only in plants"]}, {"q": "Lactic acid builds up in muscles when:", "options": ["Oxygen is too low and fermentation occurs", "Photosynthesis occurs", "Cells are dividing", "The cell is at rest"]}, {"q": "ATP stores and gives energy to the cell by:", "options": ["Turning into a protein", "Being used up as a nutrient", "Gaining and losing a phosphate group", "Forming starch"]}, {"q": "An enzyme with an optimum temperature of 37 degrees Celsius will most likely work slowest at:", "options": ["35 degrees Celsius", "80 degrees Celsius because it denatures", "40 degrees Celsius", "37 degrees Celsius"]}, {"q": "Plants release oxygen mostly because:", "options": ["Roots release gas", "Glucose is burned", "Water is split in the light reactions", "Respiration makes it"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 3: Energy for Life, Photosynthesis and Respiration$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,1,1,0,2,1,2}'::int[], array[$j$Chloroplasts contain chlorophyll and capture light energy.$j$,$j$Photosynthesis makes glucose and releases oxygen.$j$,$j$Oxygen is the final electron acceptor and glucose is the fuel.$j$,$j$Glycolysis splits glucose into pyruvate in the cytoplasm.$j$,$j$Muscle cells switch to lactic acid fermentation when oxygen is limited.$j$,$j$ATP becomes ADP when the third phosphate is released, and it is recharged.$j$,$j$High heat denatures the enzyme.$j$,$j$The oxygen comes from splitting water molecules.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 3: Energy for Life, Photosynthesis and Respiration$j$ on conflict (item_id) do nothing;
